local function name(src) local p=exports['friese-core']:GetPlayer(src); return p and ((p.PlayerData.charinfo.firstname or '')..' '..(p.PlayerData.charinfo.lastname or '')) or GetPlayerName(src) end
local function job(src) local p=exports['friese-core']:GetPlayer(src); return p and p.PlayerData.job and p.PlayerData.job.name or 'unemployed' end
local function send(src, channel, text, color, scope)
 local payload={name=name(src),source=src,channel=channel,message=text,color=color or '#eaf2ff',time=os.date('%H:%M')}
 if scope=='local' then local ped=GetPlayerPed(src); local c=GetEntityCoords(ped); for _,id in ipairs(GetPlayers()) do local target=GetPlayerPed(tonumber(id)); if #(GetEntityCoords(target)-c)<=Config.LocalChatDistance then TriggerClientEvent('friese-chat:client:message',tonumber(id),payload) end end else TriggerClientEvent('friese-chat:client:message',-1,payload) end
end
local function tell(src,msg) TriggerClientEvent('friese-chat:client:notify',src,msg) end
RegisterNetEvent('friese-chat:server:send',function(raw) local src=source; if type(raw)~='string' then return end; local msg=raw:sub(1,Config.MaxMessageLength):gsub('[<>]',''); if msg=='' then return end; if msg:sub(1,1)=='/' then ExecuteCommand(msg:sub(2)); return end; send(src,'OOC',msg,'#dce6f5','local') end)
local function command(cmd,channel,color,scope,allowed) RegisterCommand(cmd,function(src,args) if src==0 then return end; if allowed and not allowed[job(src)] then tell(src,'Je hebt geen toegang tot dit chatkanaal.'); return end; local text=table.concat(args,' '); if text=='' then tell(src,'Gebruik: /'..cmd..' [bericht]'); return end; send(src,channel,text,color,scope) end,false) end
command('me','ME','#a78bfa','local'); command('do','DO','#fbbf24','local'); command('ooc','OOC','#cbd5e1','local'); command('tweet','TWITTER','#60a5fa'); command('ad','ADVERTENTIE','#34d399'); command('report','REPORT','#fb7185')
command('politie','POLITIE','#60a5fa',nil,Config.PoliceJobs); command('ambulance','AMBULANCE','#fb7185',nil,Config.AmbulanceJobs); command('monteur','MONTEURS','#fbbf24',nil,Config.MechanicJobs)
RegisterCommand('staff',function(src,args) if src==0 or not IsPlayerAceAllowed(src,Config.AdminAce) then return end; local msg=table.concat(args,' '); if msg~='' then for _,id in ipairs(GetPlayers()) do if IsPlayerAceAllowed(tonumber(id),Config.AdminAce) then send(src,'STAFF',msg,'#f472b6') end end end end,false)
RegisterCommand('announce',function(src,args) if src==0 or not IsPlayerAceAllowed(src,Config.AdminAce) then return end; local msg=table.concat(args,' '); if msg~='' then send(src,'SERVER',msg,'#38bdf8') end end,false)
RegisterCommand('clearchat',function(src) if src==0 or not IsPlayerAceAllowed(src,Config.AdminAce) then return end; TriggerClientEvent('friese-chat:client:clear',-1) end,false)
RegisterCommand('kick',function(src,args) if src==0 or not IsPlayerAceAllowed(src,Config.AdminAce) then return end; local id=tonumber(args[1]); if id and GetPlayerName(id) then table.remove(args,1); DropPlayer(id,table.concat(args,' ')~='' and table.concat(args,' ') or 'Verwijderd door staff') end end,false)
RegisterCommand('setjob',function(src,args) if src==0 or not IsPlayerAceAllowed(src,Config.AdminAce) then return end; local id,jobName,grade=tonumber(args[1]),args[2],tonumber(args[3]); if not id or not jobName or not grade then tell(src,'Gebruik: /setjob [id] [job] [grade]'); return end; local ok=exports['friese-core']:SetJob(id,jobName,grade); tell(src,ok and 'Job bijgewerkt.' or 'Job/grade bestaat niet of speler is niet geladen.') end,false)
RegisterCommand('id',function(src) if src>0 then tell(src,'Jouw server-ID: '..src) end end,false)
